from taf.sw.nadcm.httpclient.ApiClient import ApiClient
from taf.sw.nadcm.httpclient.nadcm_uri import HwcertmanURI


class HwcertmanV1(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)

    def get_hardware_csr(self, device_id, timeout=60):
        uri = HwcertmanURI().Hardware_csr_uri + '/' + device_id
        return self.api_client.send_get_request(uri=uri, timeout=timeout)

    def generate_hardware_csr(self, device_id, country, state, locality, organization_name,
                              organization_unit_name=None, timeout=60):
        data = {"csr": {"names": [{"C": country, "ST": state, "L": locality, "O": organization_name}]}}
        if organization_unit_name:
            data['csr']['names'][0]['OU'] = organization_unit_name
        uri = HwcertmanURI().Hardware_csr_uri + '/' + device_id
        return self.api_client.send_post_request(uri=uri, json=data, timeout=timeout)

    def get_certificate_from_hw(self, device_id, certificate_type=None, update=None, timeout=60):
        uri = HwcertmanURI().Hardware_certificate_uri + '/' + device_id
        params = {}
        if certificate_type:
            params['type'] = certificate_type
        if update:
            params['update'] = update
        return self.api_client.send_get_request(uri=uri, params=params, timeout=timeout)

    def upload_externally_generated_certificate_to_hw(self, device_id, certificate_file_data,
                                                      private_key_data=None, skip_bundle=False,
                                                      timeout=60):
        files = {'certificate': certificate_file_data}
        if private_key_data:
            files["private_key"] = private_key_data
        params = {'skip_bundle': skip_bundle} if skip_bundle else {}
        uri = HwcertmanURI().Hardware_certificate_uri + '/' + device_id
        return self.api_client.send_post_request(uri=uri, files=files, params=params, timeout=timeout)

    def get_the_hw_certificate_from_inventory(self, device_id, certificate_type=None, timeout=60):
        uri = HwcertmanURI().inventory_cert_uri + '/' + device_id
        params = {'type': certificate_type} if certificate_type else {}
        return self.api_client.send_get_request(uri=uri, params=params, timeout=timeout)

    def delete_hw_certificate_from_inventory(self, device_id, timeout=60):
        uri = HwcertmanURI().inventory_cert_uri + '/' + device_id
        return self.api_client.send_delete_request(uri=uri, timeout=timeout)

    def generate_hw_certificate_based_on_ca(self, certificate_id, device_id, csr, validity, skip_bundle=False,
                                            timeout=60):
        uri = HwcertmanURI().cert_base_ca_uri + '/' + certificate_id
        params = {'skip_bundle': skip_bundle} if skip_bundle else {}
        data = {
                  "device_id": device_id,
                  "csr": csr,
                  "validity": validity
               }
        return self.api_client.send_post_request(uri=uri, json=data, params=params, timeout=timeout)

    def get_certificates_stored_in_db(self, certificate_id=None, timeout=60):
        uri = HwcertmanURI().certificate_uri
        params = {'id': certificate_id} if certificate_id else {}
        return self.api_client.send_get_request(uri=uri, params=params, timeout=timeout)

    def creates_csr_or_self_signed_certificate(self, csr, description, self_sign=None, not_after=None,
                                               timeout=60):
        uri = HwcertmanURI().csr_or_self_signed_cert_uri
        data = {
                 "csr": csr
               }
        if description:
            data['description'] = description
        if self_sign:
            data['selfsign'] = self_sign
        if not_after:
            data['not_after'] = not_after

        return self.api_client.send_post_request(uri=uri, json=data, timeout=timeout)

    def delete_certificate(self, certificate_id, timeout=60):
        uri = HwcertmanURI().delete_cert_or_csr_uri + '/' + certificate_id
        return self.api_client.send_delete_request(uri=uri, timeout=timeout)

    def decode_certificate(self, certificate_id, timeout=60):
        uri = HwcertmanURI().decode_cert_uri + '/' + certificate_id
        return self.api_client.send_get_request(uri=uri, timeout=timeout)
